vec3 LW = vec3(0.2126, 0.7152, 0.0722);
if (u_pass == 0) {
  // Pass 1: Sobel edge mask from luma + alpha of the layer.
  vec2 d = u_texel * u_width;
  float gx = 0.0, gy = 0.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec4 c = texture(u_tex, v_st + vec2(float(i), float(j)) * d);
      float v = dot(c.rgb, LW) + 0.5 * c.a;
      gx += v * float(i) * (j == 0 ? 2.0 : 1.0);
      gy += v * float(j) * (i == 0 ? 2.0 : 1.0);
    }
  }
  float e = smoothstep(u_threshold, u_threshold + u_softness, length(vec2(gx, gy)));
  o = vec4(vec3(e), e);
} else if (u_pass == 1) {
  // Pass 2: Gaussian-weighted golden-angle disk blur of the edge mask.
  float r = max(u_radius, 0.0);
  vec4 acc = texture(u_tex, v_st);
  float wsum = 1.0;
  if (r > 0.01) {
    for (int i = 0; i < 64; i++) {
      float fi = float(i) + 0.5;
      float rr = sqrt(fi / 64.0) * r;
      float a = fi * 2.39996323;
      vec2 off = vec2(cos(a), sin(a)) * rr * u_texel;
      float q = rr / r;
      float w = exp(-2.5 * q * q);
      acc += texture(u_tex, v_st + off) * w;
      wsum += w;
    }
  }
  o = acc / wsum;
} else {
  // Pass 3: add crisp core + blurred glow over the original layer.
  vec4 orig = texture(u_orig, v_st);
  float glow = texture(u_tex, v_st).r;
  vec2 d = u_texel * u_width;
  float gx = 0.0, gy = 0.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec4 c = texture(u_orig, v_st + vec2(float(i), float(j)) * d);
      float v = dot(c.rgb, LW) + 0.5 * c.a;
      gx += v * float(i) * (j == 0 ? 2.0 : 1.0);
      gy += v * float(j) * (i == 0 ? 2.0 : 1.0);
    }
  }
  float core = smoothstep(u_threshold, u_threshold + u_softness, length(vec2(gx, gy)));
  vec3 sc = orig.a > 0.001 ? orig.rgb / orig.a : u_color;
  vec3 hsv = rgb2hsv(clamp(sc, 0.0, 1.0));
  hsv.y = max(hsv.y, 0.6);
  hsv.z = 1.0;
  vec3 col = mix(u_color, hsv2rgb(hsv), u_sourceColor);
  vec4 base = orig * u_original;
  vec3 add = col * (glow * u_intensity + core * u_core);
  float ga = clamp(max(add.r, max(add.g, add.b)), 0.0, 1.0);
  float a = base.a + ga * (1.0 - base.a);
  o = vec4(min(base.rgb + add, vec3(a)), a);
}
